class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        longest=0
        for i in range(1,len(arr)-1):
            j=i
            z=i
            left_steps=0
            right_steps=0
            while arr[j+1]<arr[j] or arr[z-1]<arr[z]:
                if z<0 or j>len(arr)-1:
                    break
                if arr[j+1]<arr[j]:
                    j+=1
                    right_steps+=1
                if arr[z-1]<arr[z]:
                    z-=1
                    left_steps+=1
            if right_steps>0 and left_steps>0:
                if (right_steps+left_steps+1)>longest:
                    longest=right_steps+left_steps+1
        return longest

class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        longest=0
        arr.insert(0,arr[0]+1)
        arr.append(arr[-1]+1)
        for i in range(1,len(arr)-1):
            j=i
            z=i
            while arr[j+1] < arr[j] or arr[z-1] < arr[z]:
                if arr[j+1]<arr[j]:
                    j+=1
                if arr[z-1]<arr[z]:
                    z-=1
            if j-i>0 and i-z>0:
                if (j-z+1)>longest:
                    longest=j-z+1
        return longest

class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        longest = 0

        for i in range(1, len(arr) - 1):
            # i must be a peak
            if arr[i-1] < arr[i] and arr[i] > arr[i+1]:
                left = i
                right = i

                while left > 0 and arr[left-1] < arr[left]:
                    left -= 1

                while right < len(arr) - 1 and arr[right] > arr[right+1]:
                    right += 1

                longest = max(longest, right - left + 1)

        return longest

