class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        a=[]
        for i in range(len(s)):
            for j in range(i):
                if len(set(s[j:i]))==len(list(s[j:i])):
                    a.append(s[j:i])
        for j in range(1,len(a)):
            if len(a[j-1])>len(a[j]):
                a[j-1],a[j]=a[j],a[j-1]
        return len(a[-1])

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        a=[]
        for i in range(len(s)+1):
            for j in range(i):
                if len(set(s[j:i]))==len(list(s[j:i])):
                    a.append(s[j:i])
        if len(a)==1:
            return len(a[0])
        if len(a)==0:
            return 0
        else:
            return(len(sorted(a,key=len)[-1]))

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        charSet=set()
        l=0
        res=0
        for r in range(len(s)):
            while s[r] in charSet:
                charSet.remove(s[l])
                l+=1
            charSet.add(s[r])
            res=max(res,r-l+1)
        return res

