class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        if len(nums)<2:
            return False
        else:
            i=0
            j=1
            while j<len(nums):
                while (j-i)<=k:
                    if nums[j]==nums[i]:
                        return True
                    else:
                        j+=1
                i+=1
            return False

class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        i=0
        while i<len(nums)-1:
            j=i+1
            while (j-i)<=k:
                if j==len(nums):
                    break
                if nums[j]==nums[i]:
                    return True
                else:
                    j+=1
            i+=1
        return False

class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        window=set()
        for right in range(len(nums)):
            if nums[right] in window:
                return True
            window.add(nums[right])
            if len(window)>k:
                window.remove(nums[right-k])
        return False

